  'This course develops nutrition and wellness practice across evidence literacy, digestion and metabolism, macronutrients and micronutrients, dietary guidance, assessment, the life cycle, physical activity, chronic disease prevention, non-stigmatizing weight care, food safety, mental health, food access, counseling, and an applied portfolio.',
  $nawjson${"slug": "nutrition-and-wellness", "title": "Nutrition and Wellness", "description": "This course develops nutrition and wellness practice across evidence literacy, digestion and metabolism, macronutrients and micronutrients, dietary guidance, assessment, the life cycle, physical activity, chronic disease prevention, non-stigmatizing weight care, food safety, mental health, food access, counseling, and an applied portfolio.", "topics": [{"id": "5b1cd070-d195-4628-b207-a3c929499317", "type": "topic", "title": "Nutrition Science, Wellness, and Evidence-Based Practice", "description": "Students learn nutrition as an evidence-based health science, not a collection of diet rules, and practice judging claims with scientific discipline.", "children": [{"id": "567bcece-2489-4f1a-90e3-e0aee2828d47", "type": "subtopic", "title": "Nutrition as a science", "description": "The point is to understand nutrition claims through biology, chemistry, epidemiology, and uncertainty.", "children": [{"id": "e8a6dbf8-b374-49ae-b691-214dd0a252a8", "type": "concept", "title": "Nutrients, foods, meals, and dietary patterns"}, {"id": "80567640-ee7e-4189-a9e1-09cbef44a433", "type": "concept", "title": "Correlation, causation, and plausible mechanisms"}, {"id": "4ac680a1-4f20-4d3f-8b65-6c737383a6a5", "type": "concept", "title": "Population guidance versus individual care"}]}, {"id": "ec56c54c-03fa-4619-857b-aadba3169c2a", "type": "subtopic", "title": "Wellness framework", "description": "Students learn that nutrition supports wellness alongside movement, sleep, stress, relationships, and environment.", "children": [{"id": "df08bb3f-e105-4b7b-9e2e-d9a16cc53c24", "type": "concept", "title": "Physical, mental, social, and occupational wellness"}, {"id": "42d58bd6-f3ef-4f44-bdc5-87d5c3ce341c", "type": "concept", "title": "Prevention and health promotion"}, {"id": "2afc7d0f-e5b5-475a-bf3b-a58502ab32fd", "type": "concept", "title": "Limits of nutrition-only explanations"}]}, {"id": "01fcd895-24e5-4e6c-8e8c-b5983b19f95f", "type": "subtopic", "title": "Evidence literacy", "description": "Students practice separating trustworthy guidance from trends, anecdotes, and commercial persuasion.", "children": [{"id": "14ef7ce8-6c3d-4cc9-b1bc-36dd245cb890", "type": "concept", "title": "Hierarchy of evidence and study designs"}, {"id": "04f677cb-a1aa-45c3-9aff-87fff57858e3", "type": "concept", "title": "Systematic reviews and guidelines"}, {"id": "506c66bf-ffce-4060-be98-6b093f776ba3", "type": "concept", "title": "Conflict of interest, bias, and misinformation"}]}]}, {"id": "fedf98d1-caac-4223-88d9-590168f26f5e", "type": "topic", "title": "Digestion, Absorption, Metabolism, and Energy Balance", "description": "This module explains how food becomes usable energy and tissue, and how metabolism connects nutrition to daily function and long-term health.", "children": [{"id": "b0bbe2b6-6186-4fe5-b111-34c66aed83e0", "type": "subtopic", "title": "Digestive physiology", "description": "Students learn how the gastrointestinal tract processes food and regulates nutrient availability.", "children": [{"id": "848b4add-0d5b-44bc-be8d-48b6d8717460", "type": "concept", "title": "Mouth, stomach, small intestine, colon, liver, gallbladder, and pancreas"}, {"id": "c0f1da27-e956-4ff5-9572-8065f92b66ac", "type": "concept", "title": "Enzymes, bile, motility, and absorption"}, {"id": "2588fd8a-d992-4548-973d-a689f266db02", "type": "concept", "title": "Fiber, transit, and gut barrier basics"}]}, {"id": "138780a5-d44f-41cd-96af-28cbd942ddff", "type": "subtopic", "title": "Metabolism foundations", "description": "The gist is how cells turn nutrients into energy, storage molecules, and body structures.", "children": [{"id": "51d2a180-61ff-4421-ad49-6a19ec923ac4", "type": "concept", "title": "ATP and energy pathways"}, {"id": "97a940a9-0ea7-41c4-a2a5-89d17a91293c", "type": "concept", "title": "Glycolysis, beta oxidation, and amino acid metabolism overview"}, {"id": "1d4dafd4-d7ca-4a09-946f-bb7f32e40c36", "type": "concept", "title": "Fed, fasting, and exercise states"}]}, {"id": "22c13988-240b-4370-82da-6060cef0f18a", "type": "subtopic", "title": "Energy balance", "description": "Students learn energy balance as a dynamic system rather than a simple moral equation.", "children": [{"id": "ff57e670-2789-4933-95b8-fa07ee6bcd71", "type": "concept", "title": "Basal metabolic rate and total daily energy expenditure"}, {"id": "377ca619-2fd8-4df1-bb2e-94144151aa31", "type": "concept", "title": "Appetite, satiety, hormones, and environment"}, {"id": "650c853b-407b-423d-9b4a-f3968286d2d0", "type": "concept", "title": "Adaptive responses and measurement limits"}]}]}, {"id": "179b0091-ce3c-45e5-a144-373ef3c0d859", "type": "topic", "title": "Macronutrients, Dietary Patterns, and Food Quality", "description": "Students study carbohydrate, protein, fat, and whole dietary patterns so they can evaluate meals in context rather than nutrient-by-nutrient fragments.", "children": [{"id": "8ce70acc-7f8a-498a-b776-4e1a16be6d9a", "type": "subtopic", "title": "Carbohydrates", "description": "Students evaluate carbohydrate quality, digestion, and glycemic impact in real foods.", "children": [{"id": "b3078fa0-2e20-4509-92fa-fd209b2c624d", "type": "concept", "title": "Sugars, starches, fiber, and resistant starch"}, {"id": "dc42b109-269b-4670-9b73-60991761820c", "type": "concept", "title": "Glycemic index and glycemic load"}, {"id": "8f715519-5543-4a29-81fd-1f42a587f229", "type": "concept", "title": "Whole grains, fruits, vegetables, and added sugars"}]}, {"id": "b30086bb-4d5e-4388-b00f-5c717ec45520", "type": "subtopic", "title": "Protein", "description": "Students learn protein needs, quality, and distribution for growth, repair, immunity, and aging.", "children": [{"id": "316b8247-21b2-4296-a6a7-1fcd7dc64e27", "type": "concept", "title": "Essential amino acids and protein quality"}, {"id": "518d4ea8-a7d9-4790-b8ef-d7af09d6ea16", "type": "concept", "title": "Protein needs across activity and life stage"}, {"id": "596600ba-db1d-4f75-a77a-dc82373a2fcd", "type": "concept", "title": "Plant and animal protein sources"}]}, {"id": "74c61dce-1e91-4dfd-958c-23dfcc6e5ce6", "type": "subtopic", "title": "Fats and dietary patterns", "description": "Students connect fat types and overall patterns to health outcomes.", "children": [{"id": "5c1c2b61-622a-4c2e-852d-119274b6b6ca", "type": "concept", "title": "Saturated, unsaturated, trans, omega-3, and omega-6 fats"}, {"id": "60abe5f2-f096-48e3-9f70-f76ad303e854", "type": "concept", "title": "Mediterranean, DASH, vegetarian, and culturally specific patterns"}, {"id": "db840d9c-38fa-4e64-a869-61ed64ee154c", "type": "concept", "title": "Ultra-processed foods, food matrices, and diet quality"}]}]}, {"id": "666a46e6-8e8b-4a02-a8a2-5b5bcc45aed4", "type": "topic", "title": "Vitamins, Minerals, Hydration, and Supplement Safety", "description": "This topic covers micronutrient and fluid needs, deficiency and excess, and responsible use of supplements.", "children": [{"id": "be66df98-d481-4edd-a740-e4754649cd19", "type": "subtopic", "title": "Vitamins", "description": "Students learn major vitamin functions, deficiency patterns, toxicity risks, and food sources.", "children": [{"id": "cab2fea2-bf10-43d8-b23b-6e6fb1b11557", "type": "concept", "title": "Fat-soluble vitamins A, D, E, and K"}, {"id": "2b2a6da3-2629-430e-8e41-41e12fcb27cc", "type": "concept", "title": "Water-soluble B vitamins and vitamin C"}, {"id": "350b1fe8-ecf0-416f-9048-9ce6294cabf1", "type": "concept", "title": "Fortification, deficiency, and upper limits"}]}, {"id": "7711d1f2-8063-4304-ab9c-e9858c0f5b0c", "type": "subtopic", "title": "Minerals", "description": "Students connect minerals to bone, blood, fluid balance, nerves, muscles, and chronic disease risk.", "children": [{"id": "50625c88-a283-40ef-b4b1-371a60d88fa0", "type": "concept", "title": "Calcium, iron, zinc, iodine, selenium, magnesium, sodium, and potassium"}, {"id": "7cbe60a5-ab55-483a-