set
  title = 'Nutrition and Wellness',
  goal = 'Nutrition and Wellness',
  summary = 'This course develops nutrition and wellness practice across evidence literacy, digestion and metabolism, macronutrients and micronutrients, dietary guidance, assessment, the life cycle, physical activity, chronic disease prevention, non-stigmatizing weight care, food safety, mental health, food access, counseling, and an applied portfolio.',
  data = $nawjson${"slug": "nutrition-and-wellness", "title": "Nutrition and Wellness", "description": "This course develops nutrition and wellness practice across evidence literacy, digestion and metabolism, macronutrients and micronutrients, dietary guidance, assessment, the life cycle, physical activity, chronic disease prevention, non-stigmatizing weight care, food safety, mental health, food access, counseling, and an applied portfolio.", "topics": [{"id": "5b1cd070-d195-4628-b207-a3c929499317", "type": "topic", "title": "Nutrition Science, Wellness, and Evidence-Based Practice", "description": "Students learn nutrition as an evidence-based health science, not a collection of diet rules, and practice judging claims with scientific discipline.", "children": [{"id": "567bcece-2489-4f1a-90e3-e0aee2828d47", "type": "subtopic", "title": "Nutrition as a science", "description": "The point is to understand nutrition claims through biology, chemistry, epidemiology, and uncertainty.", "children": [{"id": "e8a6dbf8-b374-49ae-b691-214dd0a252a8", "type": "concept", "title": "Nutrients, foods, meals, and dietary patterns"}, {"id": "80567640-ee7e-4189-a9e1-09cbef44a433", "type": "concept", "title": "Correlation, causation, and plausible mechanisms"}, {"id": "4ac680a1-4f20-4d3f-8b65-6c737383a6a5", "type": "concept", "title": "Population guidance versus individual care"}]}, {"id": "ec56c54c-03fa-4619-857b-aadba3169c2a", "type": "subtopic", "title": "Wellness framework", "description": "Students learn that nutrition supports wellness alongside movement, sleep, stress, relationships, and environment.", "children": [{"id": "df08bb3f-e105-4b7b-9e2e-d9a16cc53c24", "type": "concept", "title": "Physical, mental, social, and occupational wellness"}, {"id": "42d58bd6-f3ef-4f44-bdc5-87d5c3ce341c", "type": "concept", "title": "Prevention and health promotion"}, {"id": "2afc7d0f-e5b5-475a-bf3b-a58502ab32fd", "type": "concept", "title": "Limits of nutrition-only explanations"}]}, {"id": "01fcd895-24e5-4e6c-8e8c-b5983b19f95f", "type": "subtopic", "title": "Evidence literacy", "description": "Students practice separating trustworthy guidance from trends, anecdotes, and commercial persuasion.", "children": [{"id": "14ef7ce8-6c3d-4cc9-b1bc-36dd245cb890", "type": "concept", "title": "Hierarchy of evidence and study designs"}, {"id": "04f677cb-a1aa-45c3-9aff-87fff57858e3", "type": "concept", "title": "Systematic reviews and guidelines"}, {"id": "506c66bf-ffce-4060-be98-6b093f776ba3", "type": "concept", "title": "Conflict of interest, bias, and misinformation"}]}]}, {"id": "fedf98d1-caac-4223-88d9-590168f26f5e", "type": "topic", "title": "Digestion, Absorption, Metabolism, and Energy Balance", "description": "This module explains how food becomes usable energy and tissue, and how metabolism connects nutrition to daily function and long-term health.", "children": [{"id": "b0bbe2b6-6186-4fe5-b111-34c66aed83e0", "type": "subtopic", "title": "Digestive physiology", "description": "Students learn how the gastrointestinal tract processes food and regulates nutrient availability.", "children": [{"id": "848b4add-0d5b-44bc-be8d-48b6d8717460", "type": "concept", "title": "Mouth, stomach, small intestine, colon, liver, gallbladder, and pancreas"}, {"id": "c0f1da27-e956-4ff5-9572-8065f92b66ac", "type": "concept", "title": "Enzymes, bile, motility, and absorption"}, {"id": "2588fd8a-d992-4548-973d-a689f266db02", "type": "concept", "title": "Fiber, transit, and gut barrier basics"}]}, {"id": "138780a5-d44f-41cd-96af-28cbd942ddff", "type": "subtopic", "title": "Metabolism foundations", "description": "The gist is how cells turn nutrients into energy, storage molecules, and body structures.", "children": [{"id": "51d2a180-61ff-4421-ad49-6a19ec923ac4", "type": "concept", "title": "ATP and energy pathways"}, {"id": "97a940a9-0ea7-41c4-a2a5-89d17a91293c", "type": "concept", "title": "Glycolysis, beta oxidation, and amino acid metabolism overview"}, {"id": "1d4dafd4-d7ca-4a09-946f-bb7f32e40c36", "type": "concept", "title": "Fed, fasting, and exercise states"}]}, {"id": "22c13988-240b-4370-82da-6060cef0f18a", "type": "subtopic", "title": "Energy balance", "description": "Students learn energy balance as a dynamic system rather than a simple moral equation.", "children": [{"id": "ff57e670-2789-4933-95b8-fa07ee6bcd71", "type": "concept", "title": "Basal metabolic rate and total daily energy expenditure"}, {"id": "377ca619-2fd8-4df1-bb2e-94144151aa31", "type": "concept", "title": "Appetite, satiety, hormones, and environment"}, {"id": "650c853b-407b-423d-9b4a-f3968286d2d0", "type": "concept", "title": "Adaptive responses and measurement limits"}]}]}, {"id": "179b0091-ce3c-45e5-a144-373ef3c0d859", "type": "topic", "title": "Macronutrients, Dietary Patterns, and Food Quality", "description": "Students study carbohydrate, protein, fat, and whole dietary patterns so they can evaluate meals in context rather than nutrient-by-nutrient fragments.", "children": [{"id": "8ce70acc-7f8a-498a-b776-4e1a16be6d9a", "type": "subtopic", "title": "Carbohydrates", "description": "Students evaluate carbohydrate quality, digestion, and glycemic impact in real foods.", "children": [{"id": "b3078fa0-2e20-4509-92fa-fd209b2c624d", "type": "concept", "title": "Sugars, starches, fiber, and resistant starch"}, {"id": "dc42b109-269b-4670-9b73-60991761820c", "type": "concept", "title": "Glycemic index and glycemic load"}, {"id": "8f715519-5543-4a29-81fd-1f42a587f229", "type": "concept", "title": "Whole grains, fruits, vegetables, and added sugars"}]}, {"id": "b30086bb-4d5e-4388-b00f-5c717ec45520", "type": "subtopic", "title": "Protein", "description": "Students learn protein needs, quality, and distribution for growth, repair, immunity, and aging.", "children": [{"id": "316b8247-21b2-4296-a6a7-1fcd7dc64e27", "type": "concept", "title": "Essential amino acids and protein quality"}, {"id": "518d4ea8-a7d9-4790-b8ef-d7af09d6ea16", "type": "concept", "title": "Protein needs across activity and life stage"}, {"id": "596600ba-db1d-4f75-a77a-dc82373a2fcd", "type": "concept", "title": "Plant and animal protein sources"}]}, {"id": "74c61dce-1e91-4dfd-958c-23dfcc6e5ce6", "type": "subtopic", "title": "Fats and dietary patterns", "description": "Students connect fat types and overall patterns to health outcomes.", "children": [{"id": "5c1c2b61-622a-4c2e-852d-119274b6b6ca", "type": "concept", "title": "Saturated, unsaturated, trans, omega-3, and omega-6 fats"}, {"id": "60abe5f2-f096-48e3-9f70-f76ad303e854", "type": "concept", "title": "Mediterranean, DASH, vegetarian, and culturally specific patterns"}, {"id": "db840d9c-38fa-4e64-a869-61ed64ee154c", "type": "concept", "title": "Ultra-processed foods, food matrices, and diet quality"}]}]}, {"id": "666a46e6-8e8b-4a02-a8a2-5b5bcc45aed4", "type": "topic", "title": "Vitamins, Minerals, Hydration, and Supplement Safety", "description": "This topic covers micronutrient and fluid needs, deficiency and excess, and responsible use of supplements.", "children": [{"id": "be66df98-d481-4edd-a740-e4754649cd19", "type": "subtopic", "title": "Vitamins", "description": "Students learn major vitamin functions, deficiency patterns, toxicity risks, and food sources.", "children": [{"id": "cab2fea2-bf10-43d8-b23b-6e6fb1b11557", "type": "concept", "title": "Fat-soluble vitamins A, D, E, and K"}, {"id": "2b2a6da3-2629-430e-8e41-41e12fcb27cc", "type": "concept", "title": "Water-soluble B vitamins and vitamin C"}, {"id": "350b1fe8-ecf0-416f-9048-9ce6294cabf1", "type": "concept", "title": "Fortification, deficiency, and upper limits"}]}, {"id": "7711d1f2-8063-4304-ab9c-e9858c0f5b0c", "type": "subtopic", "title": "Minerals", "description": "Students connect minerals to bone, blood, fluid balance, nerves, muscles, and chronic disease risk.", "children": [{"id": "50625c88-a283-40ef-b4b1-371a60d88fa0", "type": "concept", "title": "Calcium, iron, zinc, iodine, selenium, magnesium, sodium, and potassium"}, {"id": "7cbe60a5-ab55-483a-86ea-710e9d0b9757", "type": "concept", "title": "Bioavailability and inhibitors/enhancers"}, {"id": "71c631db-cd7f-4fba-8b8a-1d6e615da8d7", "type": "concept", "title": "Deficiency, excess, and special populations"}]}, {"id": "891d7649-f174-4a4b-a1e9-6011e04bd549", "type": "subtopic", "title": "Hydration and supplements", "description": "Students learn to evaluate fluids and supplements for benefit, risk, quality, and evidence.", "children": [{"id": "f0d68a34-0d9c-48e9-befd-d6cd769790b7", "type": "concept", "title": "Water balance and electrolytes"}, {"id": "c5e46e47-eace-4301-b96d-230ea64783ed", "type": "concept", "title": "Caffeine, alcohol, and sugar-sweetened beverages"}, {"id": "8bd0e450-dc04-403e-b572-0cd51aac0f8e", "type": "concept", "title": "Supplement regulation, interactions, and NIH ODS fact sheets"}]}]}, {"id": "7ea1453e-9fb5-424c-a4c7-366440401fd5", "type": "topic", "title": "Dietary Guidelines, Food Labels, MyPlate, and Consumer Nutrition Skills", "description": "Students translate nutrition science into practical food choices using public guidance, labels, portions, and meal-planning tools.", "children": [{"id": "40043f47-df3b-49db-925a-95c0e4fc9c0e", "type": "subtopic", "title": "Dietary guidance", "description": "Students learn how public guidance translates evidence into broad, practical recommendations.", "children": [{"id": "2d39084f-2824-4107-bd4f-7c20e09c3744", "type": "concept", "title": "Dietary Guidelines for Americans"}, {"id": "5100c4a2-9595-4903-908b-493a8c4e764d", "type": "concept", "title": "USDA MyPlate food groups"}, {"id": "a9d24eed-49f2-41ea-97ea-013339010ca5", "type": "concept", "title": "Healthy eating patterns across budgets and cultures"}]}, {"id": "01df3fa4-110b-4971-9ba1-12b7b60fafee", "type": "subtopic", "title": "Food labels", "description": "Students practice reading labels as decision tools rather than marketing surfaces.", "children": [{"id": "ff872ad1-c5e0-487e-b633-d3b3cbebfabd", "type": "concept", "title": "Serving sizes and calories"}, {"id": "fbad09e9-43e0-40b8-932d-f8cec45c3ede", "type": "concept", "title": "Percent Daily Value, sodium, added sugar, fiber, and saturated fat"}, {"id": "72532d6f-c821-4fb8-9c90-2d6f43a4c107", "type": "concept", "title": "Ingredient lists, claims, and front-of-package labeling"}]}, {"id": "4f612b1b-b391-453c-8bcb-2311d7c877f4", "type": "subtopic", "title": "Meal planning skills", "description": "Students learn practical planning for real life constraints.", "children": [{"id": "439743f1-bd92-421c-bee2-e08086ef79e9", "type": "concept", "title": "Balanced meals and snacks"}, {"id": "f96ffbb5-8abd-492b-a572-1c661977a3d4", "type": "concept", "title": "Grocery planning, cooking basics, and leftovers"}, {"id": "2f11582e-5be9-4fa7-8365-bf30ab46e7d4", "type": "concept", "title": "Portion awareness and mindful eating"}]}]}, {"id": "75e45e83-31c7-4895-a250-8e62767e1c6d", "type": "topic", "title": "Nutrition Assessment, Diet Analysis, and Goal Setting", "description": "This module teaches how to collect, interpret, and communicate nutrition information without overclaiming or stigmatizing.", "children": [{"id": "6fb1e7cb-4bf0-4b9e-930a-4af0419b6d22", "type": "subtopic", "title": "Dietary assessment", "description": "Students learn common ways to estimate intake and the limits of each method.", "children": [{"id": "2bd07869-e79e-436f-a255-40979c4007ce", "type": "concept", "title": "24-hour recalls, food records, and food frequency questionnaires"}, {"id": "cdcc4e6d-711f-4cc7-b0b0-e2ad02bae6a6", "type": "concept", "title": "Diet analysis software and nutrient databases"}, {"id": "ccb238b2-ec93-46ea-99b5-36b00afc75b8", "type": "concept", "title": "Recall bias, underreporting, and context"}]}, {"id": "f161ec50-bc48-48f9-ab72-095ac86a8dc3", "type": "subtopic", "title": "Health and body data", "description": "Students interpret nutrition-related data with caution and respect.", "children": [{"id": "b3f9ed54-ae1b-416b-aed0-2c973e7b62e4", "type": "concept", "title": "Anthropometrics and body composition basics"}, {"id": "2289a135-005f-44e5-9d9a-4c13ccb4febf", "type": "concept", "title": "Labs, blood pressure, medications, and clinical context"}, {"id": "91855152-de12-4f72-8f36-c71b7a6514fd", "type": "concept", "title": "Screening versus diagnosis"}]}, {"id": "0b282750-1476-4082-bf2c-f8a9463cb68a", "type": "subtopic", "title": "Goal setting", "description": "Students turn assessment into realistic, measurable, person-centered goals.", "children": [{"id": "fd9ee31a-d69f-4d84-a66b-b2334d8245dd", "type": "concept", "title": "SMART goals and readiness to change"}, {"id": "5b4438d5-e67e-44fb-a51b-5c9ce9e19a44", "type": "concept", "title": "Tracking, feedback, and self-monitoring"}, {"id": "3de2cb4f-5ba6-4487-80e8-71535c178aca", "type": "concept", "title": "When to refer to a registered dietitian or clinician"}]}]}, {"id": "98006442-c028-408d-bb34-84b08d85cff0", "type": "topic", "title": "Lifecycle Nutrition: Pregnancy, Infancy, Childhood, Adolescence, Adulthood, and Aging", "description": "Students learn how nutrient priorities change across life stages and how wellness guidance must fit developmental context.", "children": [{"id": "b893d852-1e3a-4d88-8c1a-f2f798b979aa", "type": "subtopic", "title": "Pregnancy, lactation, and infancy", "description": "Students learn early-life nutrition priorities that shape growth and long-term health.", "children": [{"id": "f2b18602-db06-4d43-b96f-c36d14bdade5", "type": "concept", "title": "Folate, iron, iodine, DHA, and gestational weight guidance"}, {"id": "8601e421-4d8a-4c86-93b4-d8785cc11a8e", "type": "concept", "title": "Breastfeeding, formula, and complementary foods"}, {"id": "71416108-47af-48e6-84e0-eff5a4fa27b6", "type": "concept", "title": "Food safety and high-risk nutrients"}]}, {"id": "da04e41b-fe14-46dc-96b0-1d3c926b1815", "type": "subtopic", "title": "Childhood and adolescence", "description": "Students study nutrition for growth, development, activity, and family routines.", "children": [{"id": "b649d54a-da36-4036-b18b-42f0925dbd9c", "type": "concept", "title": "Growth patterns and pediatric nutrient needs"}, {"id": "6eb9bbfd-10d2-41be-92e3-32bb2fdc294b", "type": "concept", "title": "School meals, picky eating, and family food environments"}, {"id": "2bdebfff-fbd7-4014-8d1c-7201f583e4ac", "type": "concept", "title": "Adolescent autonomy, sports, body image, and disordered eating risk"}]}, {"id": "f18786dc-e492-46b2-8983-c67b8e5cc46d", "type": "subtopic", "title": "Adults and older adults", "description": "Students learn how nutrition priorities change with work, family, disease risk, and aging.", "children": [{"id": "2d81fcce-e563-4ca9-8d40-031ecd09448c", "type": "concept", "title": "Cardiometabolic prevention in adulthood"}, {"id": "3f61cdf0-30ca-47e1-927f-c1a49a5b46fc", "type": "concept", "title": "Protein, vitamin D, calcium, B12, hydration, and sarcopenia in aging"}, {"id": "1401d063-b050-451b-a853-c575655b2230", "type": "concept", "title": "Medication-nutrient interactions and malnutrition risk"}]}]}, {"id": "ddb04c8f-380d-4555-a900-57a57d3647cc", "type": "topic", "title": "Nutrition, Physical Activity, Sports Performance, and Recovery", "description": "This topic links food, hydration, activity, body composition, and recovery for general wellness and athletic performance.", "children": [{"id": "8bc0434c-99c0-4be5-91cd-33f21ba0b2c2", "type": "subtopic", "title": "Fueling activity", "description": "Students connect carbohydrate, fat, and protein metabolism to movement and training.", "children": [{"id": "60f64cbb-ee72-4baf-ba10-50f7045497a3", "type": "concept", "title": "Pre-exercise, during-exercise, and post-exercise fueling"}, {"id": "e89d3c71-e0eb-4d50-a4c9-b511486775e0", "type": "concept", "title": "Endurance versus resistance training needs"}, {"id": "337a2264-bd56-4275-8009-d148b7cc292c", "type": "concept", "title": "Energy availability and relative energy deficiency in sport"}]}, {"id": "a35f4931-8047-467b-9c06-7260e2b8c92c", "type": "subtopic", "title": "Hydration and recovery", "description": "Students learn practical recovery strategies grounded in fluid, electrolyte, sleep, and meal timing.", "children": [{"id": "2f219652-9aef-477b-8603-0f66504383c5", "type": "concept", "title": "Sweat loss and sodium replacement"}, {"id": "0a24460e-0c21-42dc-9fe1-7e35272ae169", "type": "concept", "title": "Protein distribution and muscle repair"}, {"id": "77bd6335-bc6c-41b3-8d7b-360476e0a613", "type": "concept", "title": "Recovery meals, rest, and training adaptation"}]}, {"id": "ef2523a7-4209-4f19-be50-e717d05b2f2a", "type": "subtopic", "title": "Performance supplements", "description": "Students evaluate supplements through evidence, safety, and ethical risk.", "children": [{"id": "f2e9ae32-54c7-4a6b-aa24-628a1d8340f9", "type": "concept", "title": "Creatine, caffeine, protein powders, nitrate, and beta-alanine overview"}, {"id": "16fae5a6-4eb4-42d6-8f3e-7a946daf595b", "type": "concept", "title": "Supplement 411 and contamination risk"}, {"id": "5dd42287-1bcd-48ed-ba17-94860f53eb44", "type": "concept", "title": "Special populations and contraindications"}]}]}, {"id": "bc616536-33af-4104-8e6c-1b376c644cef", "type": "topic", "title": "Diet and Chronic Disease Prevention", "description": "Students study how dietary patterns influence cardiometabolic, gastrointestinal, renal, skeletal, and cancer-related risk over time.", "children": [{"id": "41f48e5e-31f4-4d93-b5b3-9f8b9faafc4f", "type": "subtopic", "title": "Cardiometabolic health", "description": "Students learn how dietary patterns influence heart disease, hypertension, diabetes, and dyslipidemia.", "children": [{"id": "191232be-2573-41a0-9a94-6014667a440b", "type": "concept", "title": "DASH, Mediterranean, fiber-rich, and low-sodium patterns"}, {"id": "3b2c8c11-5796-45a6-a492-854798d2d904", "type": "concept", "title": "Blood glucose, insulin resistance, and diabetes prevention"}, {"id": "4d5b5d36-c02d-4c50-9889-956ecdbc988a", "type": "concept", "title": "Lipids, blood pressure, inflammation, and vascular health"}]}, {"id": "1fff67b4-f26b-4a3a-a83b-84398bff97ae", "type": "subtopic", "title": "Gastrointestinal, renal, and bone health", "description": "Students connect nutrition to common organ-system risks.", "children": [{"id": "870a4961-36ce-40e9-8795-340a40a9c1f8", "type": "concept", "title": "Fiber, constipation, reflux, IBS, and inflammatory bowel disease overview"}, {"id": "8f4e24d7-6030-4b60-8b71-f41b48d0aa15", "type": "concept", "title": "Kidney stone and chronic kidney disease nutrition basics"}, {"id": "1bd7bf8c-2b7b-4ac9-9f06-7a79e5ed5acb", "type": "concept", "title": "Calcium, vitamin D, protein, and osteoporosis prevention"}]}, {"id": "eb6ed537-c7aa-466e-b916-543078ef6623", "type": "subtopic", "title": "Cancer and immune-related prevention", "description": "Students examine prevention guidance without overstating what diet can do.", "children": [{"id": "566dbc6b-68c1-48c2-a1e7-f07b53e816e5", "type": "concept", "title": "Alcohol, processed meat, fiber, body composition, and cancer risk"}, {"id": "3c155be5-5e5e-4a0f-993f-a237864828d1", "type": "concept", "title": "Immune function and adequacy"}, {"id": "fd04e104-5713-4498-b58a-5758536c8541", "type": "concept", "title": "Survivorship nutrition and referral boundaries"}]}]}, {"id": "d28f17aa-b311-4e5c-8d60-5b5381fe99f2", "type": "topic", "title": "Weight, Body Composition, Metabolic Health, and Non-Stigmatizing Care", "description": "This module develops a careful, humane approach to weight and metabolic health that avoids shame and simplistic advice.", "children": [{"id": "4950e534-e300-44e2-9250-65fd6adb438a", "type": "subtopic", "title": "Body composition", "description": "Students learn body composition concepts and measurement limits.", "children": [{"id": "0084f971-b1a4-410e-890e-ee20a103b2e0", "type": "concept", "title": "Fat mass, lean mass, bone, and water"}, {"id": "47dbeb0a-e458-4bef-83c7-8dccd7ca2c12", "type": "concept", "title": "BMI s